import { Sparkline } from "march/charts"
import { Button } from "march/ui"

// kalp atışı: "Koş" nabzı yükseltir, "Dinlen" düşürür; çizgi son 20 ölçümü gösterir
export function Heartbeat() {
  let $beats = [72, 74, 71, 73, 75, 72, 70, 74]
  const add = (d: number) => { const last = $beats[$beats.length - 1]; $beats = [...$beats, Math.max(55, Math.min(180, last + d))].slice(-20) }
  return <div sx={{ flex: ["row", "wrap", "center"], gap: 3 }}>
    <Button size="sm" on:click={() => add(14)}>🏃 Koş</Button>
    <Button size="sm" variant="secondary" on:click={() => add(-10)}>🧘 Dinlen</Button>
    <Sparkline data={() => $beats} width={160} height={40} area color={4} title="Nabız" />
    <strong>{() => `${$beats[$beats.length - 1]} bpm`}</strong>
  </div>
}

import { Sparkline } from "march/charts"
import { Card, ListRow, Badge } from "march/ui"

// borsa izleme listesi: her satırda hisse, 30 günlük eğilim, son fiyat ve değişim rozeti
const STOCKS = [
  { kod: "HADI", fiyat: [41, 42, 44, 43, 46, 48, 47, 50, 52, 51, 54] },
  { kod: "MRCH", fiyat: [88, 86, 87, 84, 82, 83, 80, 78, 79, 76, 75] },
  { kod: "KAHV", fiyat: [12, 12.4, 12.1, 12.6, 12.5, 12.9, 13.1, 12.8, 13.3, 13.2, 13.4] },
]

export function StockWatch() {
  return <Card title="İzleme listesi">
    {STOCKS.map((s) => {
      const first = s.fiyat[0], last = s.fiyat[s.fiyat.length - 1], ch = (last - first) / first
      return <ListRow title={s.kod} sub={`₺${last}`}
        trail={<div sx={{ flex: ["row", "center"], gap: 2 }}>
          <Sparkline data={s.fiyat} color={ch >= 0 ? 2 : 4} width={96} height={28} title={s.kod} />
          <Badge tone={ch >= 0 ? "success" : "danger"}>{`${ch >= 0 ? "+" : ""}${(ch * 100).toFixed(1)}%`}</Badge>
        </div>} />
    })}
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { SparklineLab } from "./SparklineLab.tsx"

// SparklineLab'in testleri: kaydedince Testler sekmesinde çalışır
test("çizgi ve alan çizilir; ekran okuyucu özeti biçimli", () => {
  const s = renderTest(() => <SparklineLab />)
  const svg = s.get(".lab-nums svg")!
  expect(svg.querySelector(".m-chart-area")).toBeTruthy()
  expect(svg.getAttribute("aria-label")!).toContain("Satış")
  expect(svg.getAttribute("aria-label")!).toContain("adet")
})

test("değer eklenince özet güncellenir", async () => {
  const s = renderTest(() => <SparklineLab />)
  const before = s.get(".lab-nums svg")!.getAttribute("aria-label")
  await s.click(".lab-add")
  expect(s.get(".lab-nums svg")!.getAttribute("aria-label")).not.toBe(before)
})

test("veri boşalınca boş metni söylenir", async () => {
  const s = renderTest(() => <SparklineLab />)
  await s.click(".lab-empty")
  expect(s.get(".lab-nums svg")!.getAttribute("aria-label")).toBe("Satış: Satış yok")
})

test("dot={false}: son nokta gizli; boyut yazılır", () => {
  const s = renderTest(() => <SparklineLab />)
  const obj = s.get(".lab-obj svg")!
  expect(obj.querySelector(".m-chart-marker")!.getAttribute("visibility")).toBe("hidden")
  expect(obj.getAttribute("width")).toBe("120")
})
